"use client";

import { zodResolver } from "@hookform/resolvers/zod";
import { Controller, useForm } from "react-hook-form";
import { toast } from "sonner";
import * as z from "zod";

import { Button } from "@/components/ui/button";
import { Field, FieldGroup, FieldLabel } from "@/components/ui/field";
import { Input } from "@/components/ui/input";
import { useChat } from "@ai-sdk/react";
import { ArrowUp, Loader2, Plus, Square } from "lucide-react";
import { MessageWall } from "@/components/messages/message-wall";
import { ChatHeader } from "@/app/parts/chat-header";
import { ChatHeaderBlock } from "@/app/parts/chat-header";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { DefaultChatTransport, UIMessage } from "ai";
import { useEffect, useState, useRef } from "react";
import { AI_NAME, CLEAR_CHAT_TEXT, OWNER_NAME, WELCOME_MESSAGE } from "@/config";
import Image from "next/image";
import Link from "next/link";
import { UploadPanel } from "@/components/ingestion/upload-panel";

const STORAGE_KEY = 'abis_chat_messages';
const TOKEN_KEY = 'abis_employee_token';

const formSchema = z.object({
  message: z.string().min(1, "Message cannot be empty"),
});

const authSchema = z.object({
  employeeId: z.string().min(1, "Employee ID is required"),
  employeeName: z.string().optional(),
});

type StoredData = {
  messages: UIMessage[];
  durations: Record<string, number>;
};

const loadMessagesFromStorage = (): StoredData => {
  if (typeof window === 'undefined') return { messages: [], durations: {} };
  const stored = localStorage.getItem(STORAGE_KEY);
  return stored ? JSON.parse(stored) : { messages: [], durations: {} };
};

const saveMessagesToStorage = (messages: UIMessage[], durations: Record<string, number>) => {
  if (typeof window === 'undefined') return;
  const data: StoredData = { messages, durations };
  localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
};

function ChatInterface({ initialToken }: { initialToken: string }) {
  const [durations, setDurations] = useState<Record<string, number>>({});
  const [token, setToken] = useState(initialToken);
  const tokenRef = useRef(initialToken);
  const welcomeMessageShownRef = useRef<boolean>(false);
  const [initialMessages] = useState<UIMessage[]>([]);
  const [transport, setTransport] = useState<any>(null);

  // Sync state and ref with prop
  useEffect(() => {
    if (initialToken) {
      setToken(initialToken);
      tokenRef.current = initialToken;
    }
  }, [initialToken]);

  // Sync ref with local state (for handleLogin)
  useEffect(() => {
    tokenRef.current = token;
  }, [token]);

  // Initialize transport ONLY on client to avoid SSR issues
  useEffect(() => {
    const t = new DefaultChatTransport({
      api: '/api/chat',
      headers: () => {
        if (!tokenRef.current) return {};
        // Use Capital 'A' for Authorization header and absolute reliability
        return { 'Authorization': `Bearer ${tokenRef.current}` };
      },
    });
    setTransport(t);
  }, []);

  const { messages, sendMessage, status, stop, setMessages } = useChat({
    messages: initialMessages,
    transport: transport || undefined,
    onError: (error) => {
      // If we get an error, it might be a token issue
      const errorMsg = error.message || '';
      if (errorMsg.includes('bearer token') || errorMsg.includes('401')) {
        toast.error('Session expired or missing. Please login again.');
      } else {
        toast.error(errorMsg || 'Request failed. Please try again.');
      }
    },
  });

  useEffect(() => {
    saveMessagesToStorage(messages, durations);
  }, [durations, messages]);

  const handleDurationChange = (key: string, duration: number) => {
    setDurations((prevDurations) => ({ ...prevDurations, [key]: duration }));
  };

  useEffect(() => {
    const stored = loadMessagesFromStorage();
    if (stored.messages.length > 0) {
      setMessages(stored.messages);
      setDurations(stored.durations);
      welcomeMessageShownRef.current = true;
    } else if (!welcomeMessageShownRef.current) {
      const welcomeMessage: UIMessage = {
        id: `welcome-${Date.now()}`,
        role: "assistant",
        parts: [{ type: "text", text: WELCOME_MESSAGE }],
      };
      setMessages([welcomeMessage]);
      saveMessagesToStorage([welcomeMessage], {});
      welcomeMessageShownRef.current = true;
    }
  }, [setMessages]);

  const form = useForm<z.infer<typeof formSchema>>({
    resolver: zodResolver(formSchema),
    defaultValues: { message: "" },
  });

  const authForm = useForm<z.infer<typeof authSchema>>({
    resolver: zodResolver(authSchema),
    defaultValues: { employeeId: "", employeeName: "" },
  });

  async function handleLogin(data: z.infer<typeof authSchema>) {
    try {
      const response = await fetch('/api/auth/token', {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify(data),
      });

      if (!response.ok) {
        const payload = await response.json().catch(() => null);
        throw new Error(payload?.error ?? 'Failed to create login token');
      }

      const { token: newToken } = await response.json() as { token: string };
      setToken(newToken);
      tokenRef.current = newToken;
      localStorage.setItem(TOKEN_KEY, newToken);
      toast.success('Employee session started');
      authForm.reset();
    } catch (error) {
      toast.error(error instanceof Error ? error.message : 'Login failed');
    }
  }

  function onSubmit(data: z.infer<typeof formSchema>) {
    if (!tokenRef.current) {
      toast.error('Please login with employee ID to start chatting.');
      return;
    }

    // Explicitly pass headers for maximum reliability
    sendMessage({ text: data.message }, {
      headers: { 'Authorization': `Bearer ${tokenRef.current}` }
    });
    form.reset();
  }

  function clearChat() {
    const newMessages: UIMessage[] = [];
    const newDurations = {};
    setMessages(newMessages);
    setDurations(newDurations);
    saveMessagesToStorage(newMessages, newDurations);
    toast.success("Chat cleared");
  }

  return (
    <div className="flex h-screen items-center justify-center font-sans dark:bg-black">
      <main className="w-full dark:bg-black h-screen relative">
        <div className="fixed top-0 left-0 right-0 z-50 bg-linear-to-b from-background via-background/50 to-transparent dark:bg-black overflow-visible pb-16">
          <div className="relative overflow-visible">
            <ChatHeader>
              <ChatHeaderBlock>
                {!token ? (
                  <form className="flex gap-2" onSubmit={authForm.handleSubmit(handleLogin)}>
                    <Input {...authForm.register('employeeId')} placeholder="Employee ID" className="h-9 w-36" />
                    <Input {...authForm.register('employeeName')} placeholder="Name (optional)" className="h-9 w-40" />
                    <Button type="submit" size="sm">Login</Button>
                  </form>
                ) : (
                  <Button size="sm" variant="outline" onClick={() => { setToken(''); tokenRef.current = ''; localStorage.removeItem(TOKEN_KEY); }}>
                    Logout
                  </Button>
                )}
              </ChatHeaderBlock>
              <ChatHeaderBlock className="justify-center items-center">
                <Avatar className="size-8 ring-1 ring-primary">
                  <AvatarImage src="/logo.png" />
                  <AvatarFallback title="AIRA Logo">
                    <div className="flex items-center justify-center w-full h-full bg-primary text-primary-foreground rounded-full">AI</div>
                  </AvatarFallback>
                </Avatar>
                <p className="tracking-tight">Chat with {AI_NAME}</p>
              </ChatHeaderBlock>
              <ChatHeaderBlock className="justify-end">
                <Button variant="outline" size="sm" className="cursor-pointer" onClick={clearChat}>
                  <Plus className="size-4" />
                  {CLEAR_CHAT_TEXT}
                </Button>
              </ChatHeaderBlock>
            </ChatHeader>
          </div>
        </div>
        <div className="h-screen overflow-y-auto px-5 py-4 w-full pt-[88px] pb-[150px]">
          <div className="flex flex-col items-center justify-end min-h-full">
            {token && <UploadPanel token={token} />}
            <MessageWall messages={messages} status={status} durations={durations} onDurationChange={handleDurationChange} />
            {status === "submitted" && (
              <div className="flex justify-start max-w-3xl w-full">
                <Loader2 className="size-4 animate-spin text-muted-foreground" />
              </div>
            )}
          </div>
        </div>
        <div className="fixed bottom-0 left-0 right-0 z-50 bg-linear-to-t from-background via-background/50 to-transparent dark:bg-black overflow-visible pt-13">
          <div className="w-full px-5 pt-5 pb-1 items-center flex justify-center relative overflow-visible">
            <div className="message-fade-overlay" />
            <div className="max-w-3xl w-full">
              <form id="chat-form" onSubmit={form.handleSubmit(onSubmit)}>
                <FieldGroup>
                  <Controller
                    name="message"
                    control={form.control}
                    render={({ field, fieldState }) => (
                      <Field data-invalid={fieldState.invalid}>
                        <FieldLabel htmlFor="chat-form-message" className="sr-only">Message</FieldLabel>
                        <div className="relative h-13">
                          <Input
                            {...field}
                            id="chat-form-message"
                            className="h-15 pr-15 pl-5 bg-card rounded-[20px]"
                            placeholder="Ask A.I.R.A. about HR/IT/Admin policies..."
                            disabled={status === "streaming"}
                            aria-invalid={fieldState.invalid}
                            autoComplete="off"
                            onKeyDown={(e) => {
                              if (e.key === "Enter" && !e.shiftKey) {
                                e.preventDefault();
                                form.handleSubmit(onSubmit)();
                              }
                            }}
                          />
                          {(status == "ready" || status == "error") && (
                            <Button className="absolute right-3 top-3 rounded-full" type="submit" disabled={!field.value.trim()} size="icon">
                              <ArrowUp className="size-4" />
                            </Button>
                          )}
                          {(status == "streaming" || status == "submitted") && (
                            <Button className="absolute right-2 top-2 rounded-full" size="icon" onClick={() => stop()}>
                              <Square className="size-4" />
                            </Button>
                          )}
                        </div>
                      </Field>
                    )}
                  />
                </FieldGroup>
              </form>
            </div>
          </div>
          <div className="w-full px-5 py-3 items-center flex justify-center text-xs text-muted-foreground">
            © {new Date().getFullYear()} {OWNER_NAME}&nbsp;<Link href="/terms" className="underline">Terms of Use</Link>
          </div>
        </div>
      </main>
    </div>
  );
}

export default function Chat() {
  const [isMounted, setIsMounted] = useState(false);
  const [authToken, setAuthToken] = useState('');

  useEffect(() => {
    setIsMounted(true);
    const storedToken = localStorage.getItem(TOKEN_KEY);
    if (storedToken) setAuthToken(storedToken);
  }, []);

  if (!isMounted) {
    return (
      <div className="flex h-screen items-center justify-center dark:bg-black overflow-hidden">
        <Loader2 className="size-8 animate-spin text-primary" />
      </div>
    );
  }

  return <ChatInterface initialToken={authToken} />;
}
